    #Node Switch
    def switch_false( self, switch: Boolean=None, false: String=None):
        """Node Switch.
        
        Jump: False

        **Fixed inputs**

        - self on socket 'True'
        - parameter 'input_type' = 'STRING'

        Parameters
        ----------
        switch : Boolean, optional
            Socket 'Switch' (default: None)
        false : String, optional
            Socket 'False' (default: None)

        Returns
        -------
        Socket
            Default output socket.
        """
        named_sockets = {'ID_True': self, 'ID_Switch': switch, 'ID_False': false}

        node = Node( 'Switch', named_sockets=named_sockets, input_type='STRING')
        return node._out
